#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Builds the demo VM on Vultr from scratch and checks it: docs/deploying.md,
# steps 1-5, plus the sandbox network checks and a model probe.
# Run from your laptop, in the team-workspace checkout:
#   bash deploy/vm-wizard.sh
# It drives the VM over SSH. The inference key goes from your hidden input to
# the VM's .env through an SSH pipe: never argv, never a local file.

TOTAL_STAGES=11

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Run state lives outside the repo: the VM's IP and logs aren't for git.
WIZ_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/team-workspace-vm"
mkdir -p "$WIZ_DIR"
ENV_FILE="$WIZ_DIR/vm.state"          # non-secret answers, for re-runs
FINDINGS="$WIZ_DIR/vm-findings.md"    # the run's record, offered for posting at the end
REMOTE_DIR=/opt/team-workspace
DEPLOY_KEY=/root/.ssh/team-workspace-deploy
INFERENCE_BASE_URL="${INFERENCE_BASE_URL:-https://api.vultrinference.com/v1}"
VULTR_INFERENCE_API_KEY=""
VM_KEY="$HOME/.ssh/team-workspace-vultr"   # dedicated key for this VM only
SSH_OPTS=(-i "$VM_KEY" -o IdentitiesOnly=yes)

record() { printf -- '- %s\n' "$1" >> "$FINDINGS"; }
vm() { ssh "${SSH_OPTS[@]}" -o BatchMode=yes -o ConnectTimeout=10 "$VM_USER@$VM_IP" "$@"; }

# Upserts KEY=<stdin> into the VM's .env as the hub user, keeping mode 600.
# The script travels base64-encoded in the command; the value only on stdin.
UPSERT_B64=$(base64 -w0 <<'EOF'
set -eu
key=$1; f=/opt/team-workspace/.env
IFS= read -r v || true
tmp=$(mktemp); trap 'rm -f "$tmp"' EXIT
grep -v "^$key=" "$f" > "$tmp" || true
printf '%s=%s\n' "$key" "$v" >> "$tmp"
cat "$tmp" > "$f"
EOF
)
vm_env() {
  vm "sudo -u hub bash -c \"\$(echo $UPSERT_B64 | base64 -d)\" upsert $1"
  printf '  %s✓ set%s %s in the VM .env\n' "$GREEN" "$RESET" "$1"
}

# A hidden paste can carry the terminal's bracketed-paste markers (ESC[200~
# and ESC[201~) or stray whitespace, which turn a good key into a 401.
clean_key() {
  VULTR_INFERENCE_API_KEY=$(printf '%s' "$VULTR_INFERENCE_API_KEY" \
    | sed $'s/\x1b\\[20[01]~//g' | tr -d '[:space:][:cntrl:]')
}

guide_note() {
  local n=""
  printf '\n  %sWas docs/deploying.md wrong or missing a step here? Type a note, or Enter for no:%s ' "$DIM" "$RESET"
  read -r n || true
  [[ -n "$n" ]] && record "Guide, $1: $n"
  return 0
}

check() { # check "name" <pass|fail> "detail"
  if [[ "$2" == pass ]]; then
    printf '  %s✓ PASS%s %s\n' "$GREEN" "$RESET" "$1"; record "Check PASS: $1${3:+ ($3)}"
  else
    printf '  %s✗ FAIL%s %s\n' "$RED" "$RESET" "$1"; record "Check FAIL: $1${3:+ ($3)}"
  fi
}

banner "Sandbugs VM on Vultr"
printf '\n## VM run %s\n\n' "$(date -u +'%Y-%m-%d %H:%M UTC')" >> "$FINDINGS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This runs on your laptop and drives the VM over SSH."
missing=()
for c in ssh ssh-keygen ssh-add curl gh node base64 git; do command -v "$c" >/dev/null || missing+=("$c"); done
if (( ${#missing[@]} )); then warn "missing: ${missing[*]}. Install them and re-run."; exit 1; fi
gh auth status >/dev/null 2>&1 || { warn "gh isn't logged in: run 'gh auth login' first."; exit 1; }
GH_REPO=$(cd "$REPO" && gh repo view --json nameWithOwner -q .nameWithOwner)
say "Repo: $GH_REPO (checkout at $REPO)"
pr_state=$(cd "$REPO" && gh pr view 12 --json state -q .state 2>/dev/null || echo UNKNOWN)
if [[ "$pr_state" == MERGED ]]; then default_branch=main; else default_branch=spec-1-real-pipeline; fi
note "PR #12 (the proxy IP and the deps cache) is $pr_state, so the VM should run '$default_branch'."
ask DEPLOY_BRANCH "Branch to deploy (Enter for $default_branch):"
DEPLOY_BRANCH=${DEPLOY_BRANCH:-$default_branch}
write_env DEPLOY_BRANCH "$DEPLOY_BRANCH"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "SSH key and the VM on Vultr"
if [[ -f "$VM_KEY" ]]; then
  note "Using the existing dedicated key $VM_KEY"
else
  say "Creating a dedicated SSH key for this VM: $VM_KEY"
  say "Give it a passphrase (ssh-keygen asks twice)."
  ssh-keygen -q -t ed25519 -C "team-workspace Vultr VM" -f "$VM_KEY"
fi
agent_rc=0; ssh-add -l >/dev/null 2>&1 || agent_rc=$?
if [[ $agent_rc -eq 2 ]]; then
  warn "no ssh-agent is running, and the wizard needs one for the passphrase."
  say "Start one and re-run:  eval \"\$(ssh-agent)\"   (fish: eval (ssh-agent -c))"
  exit 1
fi
ssh-add -l 2>/dev/null | grep -q "$(ssh-keygen -lf "$VM_KEY.pub" | awk '{print $2}')" \
  || { say "Adding it to your ssh-agent (enter the passphrase):"; ssh-add "$VM_KEY"; }
say "Needs the team's Vultr account."
open_url "https://my.vultr.com/settings/#settingssshkeys"
step "Add SSH Key, name it 'team-workspace', and paste this public key:"
printf '\n    %s\n\n' "$(cat "$VM_KEY.pub")"
pause "Press Enter once it's saved"
open_url "https://my.vultr.com/deploy/"
step "Choose Cloud Compute (shared CPU is fine), location close to the demo."
step "Image: Ubuntu 24.04 LTS x64. Plan: 4 vCPU / 8 GB."
step "Under SSH Keys, select only 'team-workspace'."
step "Deploy, wait until it says Running, then copy its IPv4 address."
ask VM_IP "VM public IPv4:"
write_env VM_IP "$VM_IP"
ask VM_PLAN "Plan you chose, as Vultr names it (e.g. vc2-4c-8gb):"
write_env VM_PLAN "$VM_PLAN"
record "VM: Vultr $VM_PLAN, Ubuntu 24.04, branch $DEPLOY_BRANCH"
guide_note "Create the VM"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Your admin user on the VM"
say "Vultr's Ubuntu image only has root. We create a sudo user with your SSH key,"
say "use it from now on, and (if you agree) turn root SSH logins off."
ask VM_USER "Admin username to create (Enter for $USER):"
VM_USER=${VM_USER:-$USER}
write_env VM_USER "$VM_USER"
if vm sudo -n true 2>/dev/null; then
  note "$VM_USER already works with passwordless sudo: skipping."
else
  say "Connecting as root once (accept the host key if asked)…"
  ssh "${SSH_OPTS[@]}" -o StrictHostKeyChecking=accept-new "root@$VM_IP" "bash -s -- $VM_USER" <<'EOF'
set -eu; u=$1
id "$u" >/dev/null 2>&1 || adduser --disabled-password --gecos "" "$u"
usermod -aG sudo "$u"
install -d -m 700 -o "$u" -g "$u" "/home/$u/.ssh"
install -m 600 -o "$u" -g "$u" /root/.ssh/authorized_keys "/home/$u/.ssh/authorized_keys"
echo "$u ALL=(ALL) NOPASSWD:ALL" > "/etc/sudoers.d/90-$u"; chmod 440 "/etc/sudoers.d/90-$u"
EOF
  ssh "${SSH_OPTS[@]}" -o StrictHostKeyChecking=accept-new "$VM_USER@$VM_IP" true
  vm sudo -n true && printf '  %s✓%s %s can log in and sudo\n' "$GREEN" "$RESET" "$VM_USER"
fi
if confirm "Turn off SSH logins as root? (recommended; $VM_USER keeps working)"; then
  vm "echo 'PermitRootLogin no' | sudo tee /etc/ssh/sshd_config.d/00-no-root.conf >/dev/null && sudo systemctl reload ssh"
  printf '  %s✓%s root SSH logins off\n' "$GREEN" "$RESET"
fi
guide_note "SSH access"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Repo access and clone"
say "$GH_REPO is private, so the VM gets its own read-only deploy key."
vm "sudo test -f $DEPLOY_KEY || sudo ssh-keygen -q -t ed25519 -N '' -C 'team-workspace VM' -f $DEPLOY_KEY"
vm "sudo cat $DEPLOY_KEY.pub" > "$WIZ_DIR/deploy_key.pub"
note "Public key: $(cut -c1-60 "$WIZ_DIR/deploy_key.pub")…"
if confirm "Add it to $GH_REPO as a read-only deploy key?"; then
  if out=$(gh repo deploy-key add "$WIZ_DIR/deploy_key.pub" --repo "$GH_REPO" --title "Vultr VM $VM_IP" 2>&1); then
    printf '  %s✓%s deploy key added\n' "$GREEN" "$RESET"
  elif grep -qi "already" <<<"$out"; then note "already added"
  else warn "gh said: $out"; fi
fi
say "Cloning $DEPLOY_BRANCH into $REMOTE_DIR…"
vm "bash -s -- $GH_REPO $DEPLOY_BRANCH $DEPLOY_KEY $REMOTE_DIR" <<'EOF'
set -eu; repo=$1; branch=$2; key=$3; dir=$4
root_ssh="ssh -i $key -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new"
if [ ! -d "$dir/.git" ]; then
  sudo GIT_SSH_COMMAND="$root_ssh" git clone -q -b "$branch" "git@github.com:$repo.git" "$dir"
elif [ "$(stat -c %U "$dir")" = root ]; then
  cd "$dir" && sudo GIT_SSH_COMMAND="$root_ssh" git fetch -q origin \
    && sudo git checkout -q "$branch" && sudo GIT_SSH_COMMAND="$root_ssh" git pull -q --ff-only
else
  cd "$dir" && sudo -u hub -H git fetch -q origin && sudo -u hub -H git checkout -q "$branch" \
    && sudo -u hub -H git pull -q --ff-only
fi
echo "  at $(sudo git -c safe.directory="$dir" -C "$dir" log --oneline -1)"
EOF
guide_note "Clone"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Setup script and gVisor"
say "Installs Docker, Node 24 and gVisor, creates the hub user, opens 22/80/443."
say "Takes a few minutes. The log is saved to $WIZ_DIR/setup-vm.log"
if vm "sudo $REMOTE_DIR/deploy/setup-vm.sh" 2>&1 | tee "$WIZ_DIR/setup-vm.log"; then :; else
  warn "the setup script failed: see the log above"; record "setup-vm.sh failed (see setup-vm.log)"; exit 1
fi
if grep -q "gVisor works" "$WIZ_DIR/setup-vm.log"; then
  GVISOR=runsc
  check "gVisor starts containers (docker run --runtime=runsc hello-world)" pass
else
  GVISOR=""
  check "gVisor starts containers" fail "plan $VM_PLAN"
  warn "gVisor didn't start containers on this plan."
  say "Options: destroy the VM and try another plan (re-run this wizard), or go on"
  say "with plain runc and say so in the demo."
  confirm "Go on with runc?" || exit 1
  record "Fallback: runc instead of gVisor on $VM_PLAN"
fi
write_env GVISOR "$GVISOR"
guide_note "Setup script"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Product repo and app build"
say "Hands the checkout and its deploy key to the hub user, clones the GitHub demo"
say "repo as the hub repo, installs, builds the web app and the sandbox image."
note "The demo repo must exist already: docs/deploying.md, section 3 (repo, ruleset, label, token)."
ask GITHUB_REPO "Demo repo on GitHub (owner/name):"
[[ "$GITHUB_REPO" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] || { warn "not owner/name: $GITHUB_REPO"; exit 1; }
write_env GITHUB_REPO "$GITHUB_REPO"
vm "bash -s -- $REMOTE_DIR $DEPLOY_KEY $GITHUB_REPO" <<'EOF'
set -eu; dir=$1; key=$2; demo=$3
sudo install -d -m 700 -o hub -g hub /home/hub/.ssh
sudo install -m 600 -o hub -g hub "$key" /home/hub/.ssh/deploy_key
sudo chown -R hub:hub "$dir"
cd "$dir"
sudo -u hub -H git config core.sshCommand "ssh -i /home/hub/.ssh/deploy_key -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new"
# The hub repo is a clone of the demo repo: the hub fetches its main before
# each task and pushes task/<id> to its origin. No credentials in the URL.
repo=/var/lib/team-workspace/repo
url="https://github.com/$demo.git"
if [ ! -d "$repo/.git" ]; then
  sudo -u hub -H git clone -q "$url" "$repo"
  echo "  hub repo cloned from $url"
else
  origin=$(sudo -u hub -H git -C "$repo" remote get-url origin 2>/dev/null || echo none)
  if [ "$origin" = "$url" ]; then
    echo "  hub repo already cloned from $url"
  else
    echo "  ! $repo exists with origin '$origin', not $url."
    echo "    Move it aside (sudo mv $repo $repo.old && sudo install -d -o hub -g hub $repo) and re-run."
    exit 1
  fi
fi
cd "$dir"
sudo -u hub -H env COREPACK_ENABLE_DOWNLOAD_PROMPT=0 corepack pnpm install --frozen-lockfile
sudo -u hub -H env COREPACK_ENABLE_DOWNLOAD_PROMPT=0 corepack pnpm --filter @app/web build
sudo docker build -q -t team-workspace-sandbox:latest packages/sandbox/image
EOF
printf '  %s✓%s built\n' "$GREEN" "$RESET"
guide_note "Product repo and build"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Inference key and .env"
vm "cd $REMOTE_DIR && { [ -f .env ] || sudo -u hub cp .env.example .env; } && sudo chown hub:hub .env && sudo chmod 600 .env"
if vm "sudo grep -q '^VULTR_INFERENCE_API_KEY=..*' $REMOTE_DIR/.env"; then
  note "The VM .env already has an inference key. Enter keeps it; paste to replace it."
fi
say "Copy the Vultr inference key from the team's password manager."
ask_secret VULTR_INFERENCE_API_KEY "Paste the key (hidden):"
clean_key
if [[ -n "$VULTR_INFERENCE_API_KEY" ]]; then
  printf '%s\n' "$VULTR_INFERENCE_API_KEY" | vm_env VULTR_INFERENCE_API_KEY
fi
DOMAIN="$VM_IP.sslip.io"
printf '%s\n' real                                     | vm_env RUNNER
printf '%s\n' /var/lib/team-workspace/repo             | vm_env HUB_REPO_DIR
printf '%s\n' "$REMOTE_DIR/demo/incidents.json"        | vm_env INCIDENTS_FILE
printf '%s\n' /var/lib/team-workspace/tasks            | vm_env TASKS_DIR
printf '%s\n' /var/lib/team-workspace/deps             | vm_env DEPS_CACHE_DIR
printf '%s\n' "$GVISOR"                                | vm_env SANDBOX_RUNTIME
printf '%s\n' http://172.28.0.2:8080                   | vm_env SANDBOX_PROXY_URL
printf '%s\n' "$DOMAIN"                                | vm_env DOMAIN
printf '%s\n' production                               | vm_env NODE_ENV
printf '%s\n' "$GITHUB_REPO"                           | vm_env GITHUB_REPO
if vm "sudo grep -q '^GITHUB_TOKEN=..*' $REMOTE_DIR/.env"; then
  note "The VM .env already has a GitHub token. Enter keeps it; paste to replace it."
fi
say "Copy the demo repo's fine-grained token from the team's password manager"
say "(Contents and Pull requests read/write, Metadata read; only $GITHUB_REPO)."
GITHUB_TOKEN=""
read -rs -p "  Paste the token (hidden): " GITHUB_TOKEN || true
printf '\n'
GITHUB_TOKEN=$(printf '%s' "$GITHUB_TOKEN" | sed $'s/\x1b\\[20[01]~//g' | tr -d '[:space:][:cntrl:]')
if [[ -n "$GITHUB_TOKEN" ]]; then
  printf '%s\n' "$GITHUB_TOKEN" | vm_env GITHUB_TOKEN
fi
GITHUB_TOKEN=""
guide_note ".env"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Pick and pin the model"
if [[ -z "$VULTR_INFERENCE_API_KEY" ]]; then
  say "Listing models needs the key here too (kept in memory only)."
  ask_secret VULTR_INFERENCE_API_KEY "Paste the key (hidden):"
  clean_key
fi
auth() { printf 'header = "Authorization: Bearer %s"\n' "$VULTR_INFERENCE_API_KEY"; }
if ! models=$(auth | curl -sS --fail -K - "$INFERENCE_BASE_URL/models" \
     | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{for(const m of JSON.parse(s).data??[])console.log(m.id)})'); then
  warn "couldn't list models: check the key"; exit 1
fi
say "Models on the account:"
printf '%s\n' "$models" | nl -w4 -s'  '
say ""
say "Each candidate gets the hub's real first prompt for INC-1042, 3 times."
say "A good model answers in the JSON edit format every time, with a Vitest test."
read -r -p "  Candidates to try (model ids, space-separated): " candidates
for m in $candidates; do
  say ""; say "── $m"
  printf '%s\n' "$VULTR_INFERENCE_API_KEY" \
    | INFERENCE_BASE_URL="$INFERENCE_BASE_URL" node "$REPO/deploy/probe-model.ts" "$m" 3 \
    | tee "$WIZ_DIR/probe.out" || true
  while IFS= read -r line; do record "Probe $m: $line"; done < <(grep -E '^(run|RESULT)' "$WIZ_DIR/probe.out")
done
rm -f "$WIZ_DIR/probe.out"
ask INFERENCE_MODEL "Model to pin (exact id):"
write_env INFERENCE_MODEL "$INFERENCE_MODEL"
printf '%s\n' "$INFERENCE_MODEL" | vm_env INFERENCE_MODEL
record "Pinned INFERENCE_MODEL=$INFERENCE_MODEL"
guide_note "Model"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Start everything"
vm "bash -s -- $REMOTE_DIR" <<'EOF'
set -eu; cd "$1"
sudo docker compose --env-file .env --profile vm up -d --build
sudo cp deploy/team-workspace-hub.service /etc/systemd/system/
sudo systemctl daemon-reload
sudo systemctl enable -q team-workspace-hub
sudo systemctl restart team-workspace-hub
EOF
say "Waiting for https://$DOMAIN/api/health (the first certificate can take a minute)…"
healthy=""
for _ in $(seq 1 40); do
  if curl -fsS --max-time 5 "https://$DOMAIN/api/health" >/dev/null 2>&1; then healthy=1; break; fi
  sleep 3
done
if [[ -n "$healthy" ]]; then
  check "hub answers on https://<vm-ip>.sslip.io/api/health" pass
  note "roles: $(curl -fsS "https://$DOMAIN/api/roles" | head -c 300)"
else
  check "hub answers on /api/health" fail
  warn "look at: ssh -i $VM_KEY $VM_USER@$VM_IP journalctl -u team-workspace-hub -n 50"
  pause "Press Enter to go on with the network checks anyway"
fi
guide_note "Start"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Network checks (the acceptance criteria)"
say "Each check starts a throwaway sandbox exactly like the hub does: same image,"
say "same network, ${GVISOR:-runc} runtime, read-only root, proxy at 172.28.0.2."
RT=""; [[ -n "$GVISOR" ]] && RT="--runtime=runsc"
P=http://172.28.0.2:8080
SB="sudo docker run --rm $RT --network sandbox --read-only --tmpfs /tmp:rw,exec,nosuid,size=512m --cap-drop ALL --security-opt no-new-privileges -e HOME=/tmp/home -e npm_config_cache=/tmp/home/.npm"
PX="-e npm_config_registry=http://verdaccio:4873/ -e npm_config_proxy=$P -e npm_config_https_proxy=$P -e HTTP_PROXY=$P -e HTTPS_PROXY=$P -e http_proxy=$P -e https_proxy=$P"
IMG=team-workspace-sandbox:latest
say ""

say "1/4 npm ci from Verdaccio through the proxy…"
if out=$(vm "$SB $PX $IMG sh -c 'set -e; mkdir -p /tmp/p && cd /tmp/p && npm init -y >/dev/null && npm install --package-lock-only --no-audit --no-fund is-number@7.0.0 >/dev/null && npm ci --no-audit --no-fund >/dev/null && test -f node_modules/is-number/package.json && grep -m1 -o \"http://verdaccio:4873/[^\\\"]*\" package-lock.json'" 2>&1); then
  check "npm ci in a ${GVISOR:-runc} sandbox installs from Verdaccio" pass "${out##*$'\n'}"
else
  check "npm ci in a ${GVISOR:-runc} sandbox installs from Verdaccio" fail "$(tail -n 3 <<<"$out" | tr '\n' ' ')"
fi

say "2/4 DNS from a sandbox must fail…"
if vm "$SB $IMG timeout 20 nslookup example.com" >/dev/null 2>&1; then
  check "nslookup example.com from a sandbox fails" fail "it resolved"
else
  check "nslookup example.com from a sandbox fails" pass
fi

say "3/4 a request to anything but Verdaccio lands in the denied log…"
since=$(vm 'date +%s%3N')
vm "$SB $PX $IMG sh -c 'wget -q -T 10 -O /dev/null http://example.com/; wget -q -T 10 -O /dev/null https://example.com/; true'" >/dev/null 2>&1 || true
denied=$(vm "curl -fsS 'http://127.0.0.1:8081/denied?since=$since'" 2>/dev/null || echo "")
if grep -q 'example.com' <<<"$denied"; then
  check "a non-registry request shows up in the proxy's denied log" pass "$(grep -o '"method":"[A-Z]*","target":"[^"]*"' <<<"$denied" | tr '\n' ' ')"
else
  check "a non-registry request shows up in the proxy's denied log" fail "denied log: ${denied:-empty}"
fi

say "4/4 code that ignores the proxy can't get out either…"
if vm "$SB $IMG wget -q -T 8 -O /dev/null http://1.1.1.1/" >/dev/null 2>&1; then
  check "a direct connection (no proxy) from a sandbox fails" fail "it connected"
else
  check "a direct connection (no proxy) from a sandbox fails" pass
fi
pause
guide_note "Network checks"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Record the run"
VULTR_INFERENCE_API_KEY=""
say "The record so far ($FINDINGS):"
printf '\n'; sed 's/^/    /' "$FINDINGS" | tail -n 40; printf '\n'
read -r -p "  Issue to post this run's record on (number, Enter to skip): " record_issue
if [[ -n "$record_issue" ]] && confirm "Post it as a comment on #$record_issue?"; then
  body=$(awk '/^## VM run/{buf=""} {buf=buf $0 "\n"} END{printf "%s", buf}' "$FINDINGS")
  printf '%s\n\nPosted by deploy/vm-wizard.sh.\n' "$body" | gh issue comment "$record_issue" --repo "$GH_REPO" --body-file - >/dev/null \
    && printf '  %s✓%s posted on #%s\n' "$GREEN" "$RESET" "$record_issue"
else
  SKIPPED+=("post $FINDINGS on an issue, if wanted")
fi
SKIPPED+=("optional ~/.ssh/config entry: Host tw-vm / HostName $VM_IP / User $VM_USER / IdentityFile $VM_KEY / IdentitiesOnly yes")
SKIPPED+=("fix docs/deploying.md wherever the run's guide notes say it was wrong ($FINDINGS)")
finish
